<script setup>
import { computed, reactive, ref, watch } from 'vue';
import { request } from '../../api/http';
import { session } from '../../lib/session';
const props=defineProps({open:Boolean}),emit=defineEmits(['close']);
const loading=ref(false),saving=ref(false),error=ref(''),tab=ref('master'),data=ref(null),controls=ref({});
const query=ref(''),category=ref(''),stockType=ref(''),requestFilter=ref(''),status=ref(''),setup=ref(''),expanded=ref('');
const drafts=reactive({}),therapyQuery=ref(''),selectedTherapy=ref(''),therapySection=ref('custom_consumed_items_details'),therapyRows=ref([]),therapyDirty=ref(false),newItem=ref(''),showHistory=ref(true),includeDisabled=ref(false);
const sections={custom_consumed_items_details:'Consumed Items',custom_supporting_materials:'Supporting Materials',custom_main_treatment_consumables:'Main Treatment'};
const items=computed(()=>data.value?.items||[]),branches=computed(()=>data.value?.branches||[]),inactive=computed(()=>items.value.filter(x=>+x.disabled).length);
function parse(v,d={}){if(v&&typeof v==='object')return v;try{return JSON.parse(v||'')}catch{return d}}
function base(item){const rule=data.value?.rules?.[item.name]||{};return{fields:{custom_main_category:item.custom_main_category||'',custom_stock_type:item.custom_stock_type||'',custom_material_role:item.custom_material_role||'',disabled:+item.disabled||0,safety_stock:item.safety_stock||0,lead_time_days:item.lead_time_days||0},req:data.value?.imr?.[item.name]?.req||'',blocked:rule.all?'all':(rule.branches||[]),alternatives:(data.value?.alts||[]).filter(x=>x.item===item.name).map(x=>x.alt),therapies:(data.value?.usage||[]).filter(x=>x.item===item.name).map(x=>({tt:x.tt,table:x.table,qty:x.qty})),dirty:false}}
function d(item){return drafts[item.name]||(drafts[item.name]=base(item))} function dirty(item){d(item).dirty=true}
const filtered=computed(()=>{const q=query.value.toLowerCase();return items.value.filter(i=>{const x=d(i);return(!category.value||x.fields.custom_main_category===category.value)&&(!stockType.value||x.fields.custom_stock_type===stockType.value)&&(!requestFilter.value||x.req===requestFilter.value)&&(!status.value||(status.value==='inactive')===!!x.fields.disabled)&&(!setup.value||(setup.value==='ready')===!!(x.fields.custom_main_category&&x.fields.custom_stock_type))&&(!q||`${i.name} ${i.item_name} ${i.item_group}`.toLowerCase().includes(q))})});
const changed=computed(()=>Object.entries(drafts).filter(([,x])=>x.dirty));
async function load(){loading.value=true;error.value='';try{const[a,b]=await Promise.all([request('life_item_master_control',{args:{action:'init'},csrfToken:session.csrf_token,timeoutMs:120000}),request('life_stock_request_controls',{args:{},csrfToken:session.csrf_token,timeoutMs:120000})]);data.value=a.message||a;controls.value=b.message||b;Object.keys(drafts).forEach(k=>delete drafts[k]);selectedTherapy.value||=(data.value.therapies||[])[0]?.name||'';loadTherapy()}catch(e){error.value=e.message||'Could not load controls.'}finally{loading.value=false}}
async function save(){const payload=changed.value.map(([item,x])=>({item,fields:x.fields,req:x.req,blocked:x.blocked,alternatives:x.alternatives,therapies:x.therapies}));if(!payload.length)return;saving.value=true;try{await request('life_item_master_control',{args:{action:'save',items:payload},csrfToken:session.csrf_token,timeoutMs:120000});await load()}catch(e){error.value=e.message}finally{saving.value=false}}
function toggleActive(i){d(i).fields.disabled=d(i).fields.disabled?0:1;dirty(i)} function toggleAll(i){d(i).blocked=d(i).blocked==='all'?[]:'all';dirty(i)}
function toggleBranch(i,b){let a=d(i).blocked==='all'?[...branches.value]:[...(d(i).blocked||[])];d(i).blocked=a.includes(b)?a.filter(x=>x!==b):[...a,b];dirty(i)}
function setAlts(i,e){d(i).alternatives=e.target.value.split(',').map(x=>x.trim()).filter(Boolean);dirty(i)}
function clear(){query.value=category.value=stockType.value=requestFilter.value=status.value=setup.value=''}
function csv(){const rows=[['Item','Name','Category','Stock Type','Request Use','HO Stock','Active'],...filtered.value.map(i=>[i.name,i.item_name,d(i).fields.custom_main_category,d(i).fields.custom_stock_type,d(i).req,data.value.ho?.[i.name]||0,d(i).fields.disabled?'No':'Yes'])];const blob=new Blob([rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n')]);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='stock-item-master.csv';a.click();URL.revokeObjectURL(a.href)}
const therapies=computed(()=>{const q=therapyQuery.value.toLowerCase();return(data.value?.therapies||[]).filter(x=>(includeDisabled.value||!+x.disabled)&&(!q||x.name.toLowerCase().includes(q)))});
function loadTherapy(){therapyRows.value=(data.value?.usage||[]).filter(x=>x.tt===selectedTherapy.value&&x.table===therapySection.value).map(x=>({...x}));therapyDirty.value=false}
function addTherapy(){if(newItem.value){therapyRows.value.push({item:newItem.value,qty:1});newItem.value='';therapyDirty.value=true}}
async function saveTherapy(){const old=(data.value.usage||[]).filter(x=>x.tt===selectedTherapy.value&&x.table===therapySection.value),codes=[...new Set([...old,...therapyRows.value].map(x=>x.item))];const payload=codes.map(item=>({item,therapies:[...(data.value.usage||[]).filter(x=>x.item===item&&!(x.tt===selectedTherapy.value&&x.table===therapySection.value)).map(x=>({tt:x.tt,table:x.table,qty:x.qty})),...therapyRows.value.filter(x=>x.item===item).map(x=>({tt:selectedTherapy.value,table:therapySection.value,qty:x.qty}))]}));if(!payload.length)return;saving.value=true;try{await request('life_item_master_control',{args:{action:'save',items:payload},csrfToken:session.csrf_token,timeoutMs:120000});await load()}catch(e){error.value=e.message}finally{saving.value=false}}
watch([selectedTherapy,therapySection],loadTherapy);watch(()=>props.open,v=>{if(v)load()});
</script>
<template><div v-if="open" class="shade" @click.self="emit('close')"><section class="panel"><header><div><h2>⚙ Stock Control Panel</h2><p>Branch stock request access · request windows · item active / deactivate — changes apply to all {{branches.length||11}} branches immediately</p></div><button @click="emit('close')">× Close</button></header><nav><button :class="{active:tab==='master'}" @click="tab='master'">🧭 Item Master</button><button :class="{active:tab==='request'}" @click="tab='request'">📋 Stock Request List</button><button :class="{active:tab==='window'}" @click="tab='window'">🗓 Branch Request Window <em>{{Object.keys(parse(controls.windows)).length}} set</em></button><button :class="{active:tab==='active'}" @click="tab='active'">⛔ Item Active / Deactive <em>{{inactive}} off</em></button><button :class="{active:tab==='log'}" @click="tab='log'">🧾 Change Log</button><button :class="{active:tab==='therapy'}" @click="tab='therapy'">🧪 Therapy Consumables</button></nav><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="loading">Loading live item controls…</div><template v-else-if="data">
<section v-if="tab==='therapy'" class="therapy"><div class="tbar"><input v-model="therapyQuery" placeholder="⌕ Search therapy…"><select v-model="selectedTherapy"><option v-for="t in therapies" :key="t.name">{{t.name}}</option></select><span class="badge">Active therapy</span><label><input v-model="includeDisabled" type="checkbox"> Include disabled therapies</label><button @click="showHistory=!showHistory">{{showHistory?'Hide':'Show'}} history</button></div><div class="subtabs"><button v-for="(label,key) in sections" :key="key" :class="{active:therapySection===key}" @click="therapySection=key">{{label}} <em>{{(data.usage||[]).filter(x=>x.tt===selectedTherapy&&x.table===key).length}}</em></button></div><p class="help">Deducted from branch stock when a therapy session is completed. Also checked on stock requests.</p><div class="tgrid"><main><table><thead><tr><th>#</th><th>Item (code / name)</th><th>UOM</th><th>Item group</th><th>Required qty</th><th>Check</th><th></th></tr></thead><tbody><tr v-for="(r,n) in therapyRows" :key="n"><td>{{n+1}}</td><td>{{items.find(x=>x.name===r.item)?.item_name||r.item}} — {{r.item}}</td><td>{{items.find(x=>x.name===r.item)?.stock_uom}}</td><td>{{items.find(x=>x.name===r.item)?.item_group}}</td><td><input v-model.number="r.qty" type="number" min=".01" @input="therapyDirty=true"></td><td><span class="badge">OK</span></td><td><button @click="therapyRows.splice(n,1);therapyDirty=true">×</button></td></tr></tbody></table><footer><select v-model="newItem"><option value="">Select stock item…</option><option v-for="i in items" :key="i.name" :value="i.name">{{i.item_name}} — {{i.name}}</option></select><button @click="addTherapy">+ Add Item</button><b>{{therapyRows.length}} items</b><span></span><button :disabled="!therapyDirty" @click="loadTherapy">Undo changes</button><button class="primary" :disabled="!therapyDirty||saving" @click="saveTherapy">💾 Save Changes</button></footer></main><aside v-if="showHistory"><h3>Change history</h3><article v-for="(e,n) in data.control_log||[]" :key="n"><b>{{e.by}} · {{e.at}}</b><p>{{e.what}}</p></article></aside></div></section>
<section v-else-if="tab==='window'" class="simple"><h3>Branch Request Window</h3><pre>{{parse(controls.windows)}}</pre></section><section v-else-if="tab==='log'" class="simple"><h3>Change Log</h3><article v-for="(e,n) in data.control_log||[]" :key="n"><b>{{e.by}} · {{e.at}}</b><p>{{e.what}}</p></article><p v-if="!(data.control_log||[]).length">No recorded changes.</p></section>
<template v-else><p class="help">One row per stock item. Pick values straight in the row; ▸ opens alternatives, therapy mapping, branch access and stock levels. Changes are kept until you press <b>Save</b>.</p><div class="filters"><input v-model="query" placeholder="Search item, code, group…"><select v-model="category"><option value="">All categories</option><option v-for="v in data.categories" :key="v">{{v}}</option></select><select v-model="stockType"><option value="">All stock types</option><option v-for="v in data.stock_types" :key="v">{{v}}</option></select><select v-model="requestFilter"><option value="">All request use</option><option value="M">Monthly</option><option value="C">Consumable</option><option value="B">Both</option></select><select v-model="status"><option value="">Active + deactive</option><option value="active">Active</option><option value="inactive">Deactive</option></select><select v-model="setup"><option value="">Any setup</option><option value="ready">Setup complete</option><option value="missing">Setup missing</option></select><button @click="clear">× Clear</button><b>{{filtered.length}} of {{items.length}} items</b><button @click="csv">⇩ CSV</button></div><div class="scroll"><table><thead><tr><th></th><th>Item</th><th>Category</th><th>Stock type</th><th>Request use</th><th>Role</th><th>HO stock</th><th>Branches</th><th>Alternatives</th><th>Therapies · qty/session</th><th>Active</th></tr></thead><tbody><template v-for="i in filtered" :key="i.name"><tr :class="{disabled:d(i).fields.disabled}"><td><button class="exp" @click="expanded=expanded===i.name?'':i.name">{{expanded===i.name?'▾':'▸'}}</button></td><td><strong>{{i.item_name}}</strong><small>{{i.name}} · {{i.stock_uom}} · {{i.item_group}}</small></td><td><select v-model="d(i).fields.custom_main_category" @change="dirty(i)"><option value="">— not set —</option><option v-for="v in data.categories" :key="v">{{v}}</option></select></td><td><select v-model="d(i).fields.custom_stock_type" @change="dirty(i)"><option value="">— not set —</option><option v-for="v in data.stock_types" :key="v">{{v}}</option></select></td><td><select v-model="d(i).req" @change="dirty(i)"><option value="">Default</option><option value="M">Monthly</option><option value="C">Consumable</option><option value="B">Both</option></select></td><td><select v-model="d(i).fields.custom_material_role" @change="dirty(i)"><option value="">—</option><option v-for="v in data.roles" :key="v">{{v}}</option></select></td><td>{{data.ho?.[i.name]??'—'}}</td><td><button class="pill" @click="expanded=i.name">{{d(i).blocked==='all'?'All blocked':d(i).blocked.length?`${branches.length-d(i).blocked.length} allowed`:`All ${branches.length} allowed`}}</button></td><td><button class="pill" @click="expanded=i.name">{{d(i).alternatives.length||'None'}}</button></td><td><button class="pill" @click="expanded=i.name">{{d(i).therapies.length?`${d(i).therapies.length} linked`:'Not linked'}}</button></td><td><button class="switch" :class="{on:!d(i).fields.disabled}" @click="toggleActive(i)"><i></i></button></td></tr><tr v-if="expanded===i.name" class="detail"><td colspan="11"><div><label>Alternatives (item codes)<input :value="d(i).alternatives.join(', ')" @change="setAlts(i,$event)"></label><fieldset><legend>Branch request access</legend><button @click="toggleAll(i)">{{d(i).blocked==='all'?'Allow all':'Block all'}}</button><label v-for="b in branches" :key="b"><input type="checkbox" :checked="d(i).blocked!=='all'&&!d(i).blocked.includes(b)" @change="toggleBranch(i,b)">{{b}}</label></fieldset><label>Safety stock<input v-model.number="d(i).fields.safety_stock" type="number" @input="dirty(i)"></label><label>Lead time days<input v-model.number="d(i).fields.lead_time_days" type="number" @input="dirty(i)"></label></div></td></tr></template></tbody></table></div><footer><span>{{changed.length?`${changed.length} item(s) with unsaved changes`:'No unsaved changes'}}</span><button :disabled="!changed.length" @click="Object.keys(drafts).forEach(k=>delete drafts[k])">Discard</button><button class="primary" :disabled="!changed.length||saving" @click="save">💾 Save</button><button @click="load">↻ Reload</button></footer></template></template></section></div></template>
<style scoped>
.shade{position:fixed;inset:0;z-index:2147483000;background:#10271ccc;padding:22px;display:grid;place-items:center;color:#173b2b}.panel{width:min(1760px,100%);height:min(94vh,1040px);display:flex;flex-direction:column;background:#fff;border:1px solid #c9a53a;border-radius:18px;overflow:hidden}.panel header{display:flex;justify-content:space-between;align-items:center;padding:22px 30px;background:linear-gradient(110deg,#12452f,#236e48);color:#fff}.panel h2{margin:0}.panel header p{margin:7px 0 0;color:#dcebe1}.panel button,.panel input,.panel select{font:inherit;border:1px solid #cfe0d4;border-radius:9px;background:#fff;padding:10px 13px;color:#173b2b}.panel nav{display:flex;gap:8px;padding:10px 16px 0;background:#edf6f0;border-bottom:2px solid #236e48;overflow:auto}.panel nav button,.subtabs button{border-radius:10px 10px 0 0;white-space:nowrap}.panel nav .active,.subtabs .active{background:#236e48;color:#fff;border-bottom:3px solid #dfbd53}.panel em{font-style:normal;border-radius:20px;background:#edf4ef;color:#315d46;padding:2px 8px}.help{padding:13px 20px;margin:0;background:#f6faf7;border-bottom:1px solid #dce9df}.filters{display:grid;grid-template-columns:1.5fr repeat(5,1fr) auto auto auto;gap:8px;align-items:center;padding:12px 20px}.scroll{overflow:auto;flex:1}.panel table{width:100%;border-collapse:collapse;min-width:1500px}.panel th{position:sticky;top:0;background:#205d40;color:#fff;text-align:left;padding:12px;z-index:1}.panel td{padding:10px 11px;border-bottom:1px solid #dde8e0}.panel td small{display:block;color:#708779}.panel td select{width:100%;min-width:135px}.disabled{background:#fff7f5}.pill{border-radius:20px!important;background:#fffaf0!important;border-color:#e8c66d!important}.switch{width:50px;height:28px;padding:3px!important;border-radius:30px!important;background:#bad2c3!important}.switch i{display:block;width:20px;height:20px;background:#fff;border-radius:50%}.switch.on{background:#21834e!important}.switch.on i{transform:translateX(20px)}.exp{border:0!important;background:transparent!important}.detail td{background:#f5faf6}.detail td>div{display:grid;grid-template-columns:1fr 3fr .5fr .5fr;gap:15px}.detail label{display:grid;gap:4px}.detail fieldset{display:flex;gap:9px;flex-wrap:wrap;border:1px solid #cfe0d4}.detail fieldset label{display:flex;align-items:center}.panel footer{display:flex;gap:12px;align-items:center;padding:12px 20px;border-top:1px solid #d8b651}.panel footer span{flex:1}.primary{background:#207a49!important;color:#fff!important}.error{margin:10px 20px;padding:12px;background:#fff0ed;color:#9d3427}.loading,.simple{padding:42px;overflow:auto}.therapy{display:flex;flex-direction:column;min-height:0;flex:1}.tbar{display:grid;grid-template-columns:2fr 1.2fr auto 1fr auto;gap:12px;align-items:center;padding:14px 20px}.subtabs{display:flex;gap:8px;padding:0 20px;border-bottom:1px solid #cfe0d4}.badge{padding:5px 10px;background:#e3f5e8;color:#16703d;border-radius:20px;font-weight:700}.tgrid{display:grid;grid-template-columns:minmax(0,3fr) 1fr;min-height:0;flex:1}.tgrid main{overflow:auto;display:flex;flex-direction:column}.tgrid aside{border-left:1px solid #d8b651;padding:18px;overflow:auto}.tgrid article{padding:10px 0;border-bottom:1px dashed #cfe0d4}.tgrid footer select{min-width:280px}@media(max-width:1100px){.filters{grid-template-columns:repeat(2,1fr)}.tgrid{grid-template-columns:1fr}.tgrid aside{display:none}.detail td>div{grid-template-columns:1fr}.shade{padding:6px}}
</style>
